class Driver {
  + id : int
  + name : string
  + isOnSickLeave : boolean
}

class Bus {
  + licencePlate : string
  + isInRepairShop : boolean
}

class BusRoute {
  + routeNumber : int
}

class Schedule {
  + day : date
  + shift : ShiftType
}

enum ShiftType {
  MORNING
  AFTERNOON
  NIGHT
}

class Assignment {
}

BusRoute "1" -- "*" Bus : assigned to
BusRoute "1" -- "*" Schedule : has
Bus "1" -- "*" Schedule : assigned to
Driver "1" -- "*" Assignment : assigned to
Bus "1" -- "*" Assignment : assigned to
Schedule "1" -- "*" Assignment : contains

@enduml

